package wb;
import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.function.LongSupplier;
/** Bounded background lookup, cache, throttling and old-result rejection. No Android dependency. */
public final class AddressResolver {
 public interface Lookup {JSONObject resolve(String provider,String key,double lat,double lon)throws Exception;}
 final Lookup lookup;final LongSupplier clock;final ExecutorService workers=Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"door-address");t.setDaemon(true);return t;});
 final Set<String> outstanding=new HashSet<>();boolean enabled;String provider="system",key="",status="地址解析未开启";long generation,lastAttempt=-30000,started,resultAt;double latestLat,latestLon,resultLat,resultLon;JSONObject cached;long visibleJob=-1,serial;
 public AddressResolver(LongSupplier c,Lookup l){clock=c;lookup=l;}
 public synchronized void configure(boolean on,String p,String k){p="amap".equals(p)?"amap":"system";k=k==null?"":k.trim();if(on==enabled&&p.equals(provider)&&k.equals(key))return;generation++;enabled=on;provider=p;key=k;cached=null;lastAttempt=-30000;visibleJob=-1;status=on?"等待有效定位以解析地址":"地址解析未开启";notifyAll();}
 public synchronized void consider(double lat,double lon,double accuracy){if(!enabled)return;latestLat=lat;latestLon=lon;long now=clock.getAsLong();if(cached!=null&&now-resultAt<90000&&AddressPolicy.distance(lat,lon,resultLat,resultLon)<20)return;if(outstanding.contains(provider)){if(now-started>12000)status="地址解析超时，等待后台调用结束";return;}if(now-lastAttempt<30000)return;if(provider.equals("amap")&&key.isEmpty()){status="需要填写高德 Web 服务 Key";return;}lastAttempt=now;started=now;status="正在解析地址";final long ticket=++serial,epoch=generation,began=now;final String selected=provider,secret=key;visibleJob=ticket;outstanding.add(selected);
  workers.execute(()->{synchronized(AddressResolver.this){if(!enabled||generation!=epoch||visibleJob!=ticket){outstanding.remove(selected);notifyAll();return;}}JSONObject raw=null;String failure=null;try{raw=lookup.resolve(selected,secret,lat,lon);if(raw==null||AddressPolicy.format(raw,accuracy).length()==0)failure="未查询到可用地址";}catch(Exception e){failure=e instanceof Unavailable?e.getMessage():"地址解析失败，请检查网络和服务配置";}
   synchronized(AddressResolver.this){outstanding.remove(selected);if(!enabled||generation!=epoch||visibleJob!=ticket){notifyAll();return;}long finished=clock.getAsLong();if(finished-began>12000){status="地址结果超时，已丢弃";}else if(AddressPolicy.distance(lat,lon,latestLat,latestLon)>50){status="车辆位置已变化，丢弃旧地址";}else if(failure!=null){status=failure;}else{cached=raw;resultLat=lat;resultLon=lon;resultAt=finished;status="地址已解析";}notifyAll();}
  });
 }
 public synchronized JSONObject snapshot(double lat,double lon,double accuracy){JSONObject out=new JSONObject();try{out.put("address_status",enabled?status:"地址解析未开启");if(!enabled)return out;long now=clock.getAsLong();if(outstanding.contains(provider)&&now-started>12000)out.put("address_status","地址解析超时，等待后台调用结束");if(cached==null)return out;double drift=AddressPolicy.distance(lat,lon,resultLat,resultLon);long age=now-resultAt;if(age<0||age>120000||drift>50){out.put("address_status","地址缓存过期或位置已变化，等待新地址");return out;}JSONObject address=AddressPolicy.format(cached,accuracy+drift);if(address.length()==0)return out;address.put("source",provider.equals("amap")?"amap_regeo":"android_geocoder");address.put("lookup_age_seconds",age/1000);address.put("sample_distance_m",Math.round(drift));out.put("address",address);out.put("address_status","available");}catch(Exception ignored){}return out;}
 boolean currentUsable(){long age=clock.getAsLong()-resultAt;return cached!=null&&age>=0&&age<=120000&&AddressPolicy.distance(latestLat,latestLon,resultLat,resultLon)<=50;}
 public synchronized void await(long ms){long deadline=System.nanoTime()+Math.min(2500,Math.max(0,ms))*1000000L;while(enabled&&!currentUsable()&&outstanding.contains(provider)){long left=(deadline-System.nanoTime())/1000000;if(left<=0)return;try{wait(left);}catch(InterruptedException e){Thread.currentThread().interrupt();return;}}}
 public static final class Unavailable extends Exception {public Unavailable(String message){super(message);}}
}
